<?php
function report_render_result($r,$basePage='reports'){
 $query=report_public_filters($r['filters']);$query['page']=$basePage;if($basePage==='product_detail')$query['id']=$query['product_id'];$export=$query;unset($export['page']);
 if($r['summary']){echo '<div class="mini-kpis report-summary">';foreach($r['summary'] as $k=>$v)echo '<div><span>'.e($k).'</span><strong>'.e(report_is_as_of($r['filters']['report'])&&is_numeric($v)?number_format((int)$v):$v).'</strong></div>';echo '</div>';}
 echo '<div class="card '.($r['filters']['report']==='stocks'?'stock-balance-report':'').'"><div class="card-head"><div><h3>'.e($r['title']).'</h3><p>'.e(report_period_label($r['filters'])).' · '.e(count($r['rows'])).' records</p></div><div class="modal-actions"><a class="btn secondary" href="report.php?'.e(http_build_query($export+['format'=>'xlsx'])).'">Download Excel</a><a class="btn ghost" target="_blank" rel="noopener" href="report.php?'.e(http_build_query($export+['format'=>'print'])).'">Print / Save as PDF</a></div></div>';
 echo '<p class="small muted">Generated '.e($r['generated']).' · '.e($r['user']).' · '.e(report_is_as_of($r['filters']['report'])?report_readable_filters($r['filters']):json_encode(array_filter($r['filters'],fn($v)=>$v!==''&&$v!==0),JSON_UNESCAPED_UNICODE)).'</p><div class="table-wrap"><table class="table"><thead><tr>';foreach($r['headers'] as $h)echo '<th>'.e($h).'</th>';echo '<th>Source</th></tr></thead><tbody>';$offset=max(0,(int)($_GET['offset']??0));foreach(array_slice($r['rows'],$offset,50,true) as $i=>$row){echo '<tr>';foreach($row as $column=>$v)echo '<td>'.e((($r['filters']['report']==='stocks'&&$column>=2)||($r['filters']['report']==='stock_balance_detail'&&$column>=3))?number_format((int)$v):$v).'</td>';echo '<td>'.(!empty($r['links'][$i])?'<a class="btn ghost sm" href="'.e($r['links'][$i]).'">'.($r['filters']['report']==='stocks'?'View Breakdown':'View').'</a>':'—').'</td></tr>';}if(!$r['rows'])echo '<tr><td colspan="'.(count($r['headers'])+1).'">No matching movements or records. Opening/closing rows are retained where applicable.</td></tr>';echo '</tbody>';if(!empty($r['totals_row'])){echo '<tfoot><tr class="total-row">';foreach($r['totals_row'] as $column=>$v)echo '<td><b>'.e($column>=2?number_format((int)$v):$v).'</b></td>';echo '<td></td></tr></tfoot>';}echo '</table></div><div class="modal-actions">';echo rs8_pagination(count($r['rows']),$offset,50,$query,'offset',false,'50 rows per page · Exports include all matching rows.');echo '</div>';foreach($r['notes'] as $note)echo '<p class="muted small">'.e($note).'</p>';echo '</div>';
}
